 async function openDesign(id){
  identity();
  if(!accountId||typeof id!=='string'||!/^[a-z0-9][a-z0-9-]{0,95}$/.test(id))return false;
  const account=accountId,sessionEpoch=epoch;
  if(!hubFrame||activePanel!=='browse'||state().view!=='collection'||!loaded){
   if(!await collection('browse','all')||epoch!==sessionEpoch||state().account?.id!==account||activePanel!=='browse')return false;
  }
  if(fixed(id)){inspect(id);return true;}
  return openBadge(id);
 }
