 async function mutate(path,body,button,after){if(window.navigator?.onLine===false){errorNode(Error('Reconnect before changing your collection.'));return;}if(mutationBusy){app.announce('Wait for the current collection change to finish.');return;}mutationBusy=true;writeVersion++;const serial=++mutationSerial,current=guard(),ticket=state().dialogGeneration;if(button)button.disabled=true;try{const data=await app.request('/api/cosmetics'+path,body);if(!current())return;applyInventory(data);if(typeof CustomEvent==='function')window.dispatchEvent?.(new CustomEvent('voidline:cosmetics-changed',{detail:{accountId}}));if(ticket===state().dialogGeneration)await after?.(data);refreshChrome();}catch(error){if(current()&&ticket===state().dialogGeneration)errorNode(error);}finally{if(serial===mutationSerial)mutationBusy=false;if(current()&&button?.isConnected)button.disabled=false;}}

 function sendForm(id){rememberCollection();panelIntent++;const item=fixed(id);if(!item||item.type!=='gift'||item.acquisitionPolicy==='capsule-only')return;dialog('Send a gift',`${item.name} · Free`,`${errors}<form class="vc-send-form" data-vc-form="send" data-item="${id}" data-client="${crypto.randomUUID()}"><div class="vc-send-art">${art(id)}</div><label class="vh-field">Recipient username<input name="username" required minlength="3" maxlength="24" autocomplete="off" spellcheck="false" placeholder="username" autofocus></label><p class="vc-fine">The recipient can collect or decline it. Your username is shown with the request. No payment is needed.</p><button class="vh-primary" type="submit">Review recipient & gift</button><button class="vh-secondary" type="button" data-vc-action="return" data-item="${id}">Cancel</button></form>`);}

 async function send(form){if(window.navigator?.onLine===false)return errorNode(Error('Reconnect to send a gift request.'));if(form.dataset.busy)return;const current=guard(),ticket=state().dialogGeneration,button=form.querySelector('[type="submit"]'),input=form.querySelector('input[name="username"]'),data=new FormData(form);form.dataset.busy='1';if(button)button.disabled=true;if(input)input.disabled=true;try{const transferring=form.dataset.mode==='transfer',response=await app.request('/api/cosmetics/'+(transferring?'transfers':'gifts'),{...(transferring?{instanceId:form.dataset.instance,expectedOwnershipRevision:Number(form.dataset.revision)}:{catalogId:form.dataset.item}),username:String(data.get('username')||'').trim().replace(/^@/,''),clientId:form.dataset.client,...(form.dataset.recipient?{recipientId:form.dataset.recipient}:{})});if(!current()||ticket!==state().dialogGeneration||!form.isConnected)return;if(response.acknowledged!==true||!(response.gift?.id||response.transfer?.id))throw Error('The gift was not acknowledged. Retry keeps the same request ID.');if(transferring&&response.transfer?.state&&response.transfer.state!=='pending')return transferReceipt(response.transfer.id);dialog(transferring?'Transfer request sent':'Gift request sent',transferring?'Ownership remains with you until the recipient accepts.':'The free new gift is waiting for the recipient to collect it.',`<div class="vc-inspection">${art(form.dataset.item)}<p>${esc(fixed(form.dataset.item)?.name)} · ${esc(editionLabel(fixed(form.dataset.item)))}</p><p class="vc-fine">Receipt ${esc(response.gift?.id||response.transfer?.id||'confirmed')} · @${esc(String(data.get('username')||'').trim().replace(/^@/,''))}</p><button class="vh-primary" data-vc-action="${transferring?'transfers':'inbox'}" data-box="sent">${transferring?'View sent transfers':'View sent gifts'}</button><button class="vh-secondary" data-vc-action="tab" data-tab="gifts">Back to gifts</button></div>`);app.announce('Gift request sent.');return response;}catch(error){if(current()&&ticket===state().dialogGeneration)errorNode(error);}finally{delete form.dataset.busy;if(current()&&button?.isConnected)button.disabled=false;if(current()&&input?.isConnected)input.disabled=false;}}

 function pagination(data,action,offset){return data.total>30?`<div class="vc-pagination"><button class="vh-secondary" data-vc-action="${action}" data-offset="${Math.max(0,offset-30)}" ${offset?'':'disabled'}>Previous</button><span>${offset+1}–${Math.min(offset+30,data.total)} of ${data.total}</span><button class="vh-secondary" data-vc-action="${action}" data-offset="${offset+30}" ${data.page.hasMore?'':'disabled'}>Next</button></div>`:'';}

 function transferForm(id){const instance=instances.find(i=>i.id===id);if(!instance)return app.announce('Refresh Owned gifts to load this instance.');const item=fixed(instance.catalog_id);panelIntent++;dialog('Transfer an owned gift','The recipient can accept or decline. Ownership moves only after acceptance. This is not a new free grant.',`${errors}<form class="vc-send-form" data-vc-form="transfer" data-instance="${esc(id)}" data-revision="${esc(instance.ownership_revision??0)}" data-item="${esc(instance.catalog_id)}" data-client="${crypto.randomUUID()}"><div class="vc-send-art">${art(instance.catalog_id)}</div><p><b>${esc(item?.name||'Gift')}</b></p><p class="vc-fine">${esc(editionLabel(item))} · Instance ${esc(id)}</p><label class="vh-field">Recipient username<input name="username" required minlength="3" maxlength="24" autocomplete="off" spellcheck="false" autofocus></label><button class="vh-primary" type="submit">Review transfer</button><button class="vh-secondary" type="button" data-vc-action="instances">Cancel</button></form>`);}

 function showcaseDialog(id){const instance=instances.find(i=>i.id===id);if(!instance)return app.announce('Refresh the owned collection first.');panelIntent++;dialog('Choose a showcase slot','Only your currently owned gift instances can be displayed. Sender identity stays hidden unless you choose to share it.',`${errors}<form data-vc-form="showcase" data-instance="${esc(id)}"><div class="vc-send-art">${art(instance.catalog_id)}</div><label class="vh-field">Profile slot<select name="slot">${[1,2,3].map(slot=>`<option value="${slot}">Slot ${slot}${showcase.find(s=>s.slot===slot)?' (replace current gift)':''}</option>`).join('')}</select></label><label class="vc-privacy"><input type="checkbox" name="showSender">Show the original gift sender publicly</label><button class="vh-primary" type="submit">Save showcase</button></form><button class="vh-text-button" data-vc-action="clear-showcase">Clear all showcase slots</button>`);}

 async function saveShowcase(form){const values=new FormData(form),slot=Number(values.get('slot')),id=form.dataset.instance,slots=showcase.filter(s=>s.slot!==slot&&s.instance_id!==id).map(s=>({slot:s.slot,instanceId:s.instance_id,showSender:!!s.show_sender,...(s.featured?{featured:true}:{})}));slots.push({slot,instanceId:id,showSender:values.get('showSender')==='on'});slots.sort((a,b)=>a.slot-b.slot);await mutate('/showcase',{slots},form.querySelector('[type="submit"]'),()=>{app.announce('Gift showcase saved.');return inventoryPanel();});}

 async function receivedGift(button,transfer=false){
  if(window.navigator?.onLine===false)return errorNode(Error('Reconnect to accept this gift.'));
  const d=button.dataset,id=d.item,instanceId=transfer?d.instance:'gift:'+d.gift,current=guard(),ticket=state().dialogGeneration;
  return mutate('/'+(transfer?'transfers':'gifts')+'/'+encodeURIComponent(transfer?d.transfer:d.gift)+'/open',{},button,async data=>{
   if(transfer&&data.handled===true&&['declined','cancelled'].includes(data.state)&&data.transfer?.id)return transferReceipt(data.transfer.id);
   if(data.handled!==true||transfer&&data.state!=='accepted')throw Error('The server has not confirmed this owned gift. Refresh requests before retrying.');
   if(transfer&&data.transfer?.currentlyOwned===false)return transferReceipt(d.transfer);
   let row=data.instances?.find(instance=>instance.id===instanceId&&instance.catalog_id===id);
   if(!row&&owned.has(id)){
    const exact=await app.request('/api/cosmetics/instances/'+encodeURIComponent(instanceId));
    if(!current()||ticket!==state().dialogGeneration)return;
    if(exact.instance?.id===instanceId&&exact.instance.catalog_id===id)row=exact.instance;
   }
   if(!row)throw Error('The server has not confirmed this owned gift. Refresh requests before retrying.');
   rememberInstance(row);collectedReceipt={accountId,catalogId:id,instanceId,kind:transfer?'transfer':'grant'};unwrap(id);
  });
 }

